import{_ as n}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as t,o,j as a,G as i,ae as r,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Small Business Innovation and Economic Security Act","description":"","frontmatter":{"legisId":"2026-04-13-small-business-innovation-and-economic-security-act","title":"Small Business Innovation and Economic Security Act","displayTitle":"Small Business Innovation and Economic Security Act","lawNumber":"119-83","billNumber":"S. 3971","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ83.xml","publishDate":"2026-04-13T00:00:00-05:00","industries":["technology","defense","government-operations"],"agencies":["Department of Defense"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Small Business Innovation and Economic Security Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-13-small-business-innovation-and-economic-security-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Small Business Innovation and Economic Security Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-13-small-business-innovation-and-economic-security-act\\",\\"datePublished\\":\\"2026-04-13T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-13-small-business-innovation-and-economic-security-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-04-13-small-business-innovation-and-economic-security-act.md","filePath":"congress-bills/2026-04-13-small-business-innovation-and-economic-security-act.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2026-04-13-small-business-innovation-and-economic-security-act.md"},f=Object.assign(c,{setup(d){return(m,e)=>(o(),t("div",null,[e[0]||(e[0]=a("h1",{id:"small-business-innovation-and-economic-security-act",tabindex:"-1"},[l("Small Business Innovation and Economic Security Act "),a("a",{class:"header-anchor",href:"#small-business-innovation-and-economic-security-act","aria-label":'Permalink to "Small Business Innovation and Economic Security Act"'},"​")],-1)),i(n),i(s,{list:"/congress-bills"}),e[1]||(e[1]=r('<p>Signed into law on Monday, April 13, 2026. Public Law 119-83, S. 3971.</p><p><strong>Headline:</strong> The law extends federal small-business innovation programs through 2031 while tightening security and expanding commercialization support.</p><p><strong>Why it matters:</strong> Small technology businesses retain access to SBIR and STTR funding, including a temporary pathway to awards of up to $30 million. Agencies also gain stronger tools to screen security risks and manage proposal volume.</p><p><strong>What the law does:</strong></p><ul><li>Extends the SBIR and STTR programs through September 30, 2031.</li><li>Requires reviews of applicants’ cybersecurity, foreign ties, ownership, investments, licensing arrangements, and connections to specified federal security lists.</li><li>Allows agencies to deny awards for security risks without barring applicants from future award cycles.</li><li>Creates strategic breakthrough awards of up to $30 million over 48 months, generally with prior Phase II experience and at least matching private funds.</li><li>Caps each small business’s Phase I and Phase II proposal submissions beginning in fiscal year 2027, with limited urgent-topic waivers.</li><li>Expands Phase III training, contracting help, award tracking, and technical and business assistance.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Small businesses applying for or receiving SBIR and STTR awards.</li><li>Federal agencies administering small-business research and technology funding.</li><li>Department of Defense applicants subject to added readiness, transition, and matching-fund requirements.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Entrepreneurs and small-business employees may gain continued access to federal research funding and stronger commercialization support.</li><li>Applicants will face more security screening and limits on how many proposals they may submit.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="small-business-innovation-and-economic-security-act-1" tabindex="-1">Small Business Innovation and Economic Security Act <a class="header-anchor" href="#small-business-innovation-and-economic-security-act-1" aria-label="Permalink to &quot;Small Business Innovation and Economic Security Act&quot;">​</a></h3><p>This law extends the federal Small Business Innovation Research (SBIR) and Small Business Technology Transfer (STTR) programs through September 30, 2031. It strengthens security screening, creates a temporary pathway for larger Phase II awards, limits proposal volume, improves support for commercialization, and expands program data collection and assistance.</p><p><strong>Key takeaways:</strong></p><ul><li>Federal agencies must assess applicants for cybersecurity, foreign ownership, foreign ties, investment relationships, licensing arrangements, and connections to people or entities on specified federal security lists.</li><li>Agencies may deny awards based on security risks, but may notify affected businesses of the reason when appropriate and must clarify that a denial does not prevent the business from applying in a later award cycle.</li><li>Beginning in fiscal year 2026, qualifying agencies may use a limited share of SBIR funds for strategic breakthrough awards of up to $30 million over no more than 48 months, generally requiring prior Phase II experience and at least 100 percent matching funds.</li><li>The strategic breakthrough award authority ends after September 30, 2031, and includes additional readiness, transition, and matching-fund requirements for Department of Defense awards.</li><li>Beginning in fiscal year 2027, each agency must apply equal limits on how many Phase I and Phase II proposals a small business may submit, with narrowly limited waivers for urgent topics and required reports to Congress.</li><li>The law expands Phase III training and contracting support, increases allowable technical and business assistance to $6,500 for Phase I and $50,000 for Phase II, improves award tracking, and extends related pilots and activities through September 30, 2031.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ83.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ83.xml</a></p>',15))]))}});export{h as __pageData,f as default};
